"""Keyboard-first UI for the existing opaque invoice-draft preview/save boundary."""


def invoice_draft_html() -> str:
    """Render an isolated staff page; source values are inserted only through DOM text APIs."""
    return """<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>APC Core · Invoice Draft</title>
<style>:root{--ink:#24272b;--muted:#68717c;--line:#e5e1db;--cream:#eadbc8;--paper:#fffdfa;--accent:#1d6b57;--danger:#a42e22;--warn:#8a6100}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font:14px system-ui,sans-serif}.shell{max-width:1180px;margin:auto;padding:28px}.utility{display:flex;justify-content:space-between;gap:12px;font-size:12px;color:var(--muted)}.card{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:16px;margin:14px 0}.actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center}button,input,textarea{font:inherit;padding:9px;border:1px solid var(--line);border-radius:7px}button{background:var(--accent);color:#fff;font-weight:700;cursor:pointer}button:disabled{background:#9aa29e;cursor:not-allowed}.secondary{background:#fff;color:var(--accent)}.status{color:var(--muted)}.warning{color:var(--warn);font-weight:700}.error{color:var(--danger);font-weight:700}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:10px}.field{border:1px solid var(--line);border-radius:8px;padding:10px}.field b{display:block;font-size:12px;color:var(--muted)}table{width:100%;border-collapse:collapse;margin-top:10px}th,td{border-bottom:1px solid var(--line);padding:7px;text-align:left;vertical-align:top}.review{border:2px solid var(--accent)}label{display:block;margin:7px 0;font-weight:700}textarea,input{width:100%}.conflict{border-left:4px solid var(--warn);padding-left:12px;margin:12px 0}.hidden{display:none}</style>
<body><main class="shell"><div class="utility"><a href="../">Main menu</a><span>Draft only · no automatic linking</span></div><h1>Invoice Draft</h1><p class="warning">A.W.B. is an opaque reference and is not used for automatic linking.</p>
<section class="card" aria-labelledby="opened-heading"><h2 id="opened-heading">Opened order handoff</h2><p id="opened-order" class="status">No order has been handed off from an opened Order screen.</p><div class="actions"><button id="start-draft" type="button" disabled>Start invoice draft from opened order</button><button id="add-to-draft" type="button" disabled>Add to invoice draft</button><button id="preview-draft" type="button" disabled>Review draft</button></div></section>
<section id="selection" class="card hidden" aria-labelledby="selection-heading"><h2 id="selection-heading">Visible order selection</h2><div id="selected-orders"></div></section>
<section id="draft-review" class="card review hidden" aria-labelledby="review-heading"><h2 id="review-heading">Review before saving a draft</h2><p id="review-status" class="status"></p><div id="review-details"></div><div id="conflicts"></div><label><input id="review-confirmation" type="checkbox"> I reviewed the exact selected orders, lines, conflicts, and draft-only save.</label><p>Current actor: <b id="active-actor">No active staff selected</b></p><div class="actions"><button id="save-draft" type="button" disabled>Save Draft</button></div></section>
<p id="message" role="status" class="status"></p></main>
<script>(()=>{const $=s=>document.querySelector(s),clean=node=>node.replaceChildren(),text=(node,value)=>{node.textContent=typeof value==='string'?value:String(value??'')},element=(name,value)=>{const node=document.createElement(name);if(value!==undefined)text(node,value);return node},message=$('#message'),opened=$('#opened-order'),start=$('#start-draft'),add=$('#add-to-draft'),review=$('#preview-draft'),selection=$('#selection'),selectedOrders=$('#selected-orders'),reviewPanel=$('#draft-review'),reviewDetails=$('#review-details'),conflicts=$('#conflicts'),save=$('#save-draft'),confirmation=$('#review-confirmation'),actorNode=$('#active-actor');let openedOrderId='',visibleOrder=null,selected=[],previewRef='',proposal=null;
const request=(path,options)=>fetch(path,{credentials:'same-origin',cache:'no-store',...options}).then(response=>response.ok?response.json():Promise.reject(new Error('Request failed')));const activeActor=()=>typeof window.apcCoreActiveStaff==='string'?window.apcCoreActiveStaff:'';function updateActor(){const actor=activeActor();text(actorNode,actor||'No active staff selected');return actor}window.addEventListener('apc-core-identity',updateActor);updateActor();function setMessage(value,error=false){text(message,value);message.className=error?'error':'status'}function orderCard(order){const card=element('div');card.className='field';card.append(element('b','Order'),element('div',order.order_id),element('b','Customer'),element('div',order.customer_id+' · '+order.customer_name),element('b','Provenance'),element('div','Opened saved order · read-only source evidence'));return card}function showVisibleOrder(order){visibleOrder=order;selection.classList.remove('hidden');clean(selectedOrders);selectedOrders.append(orderCard(order));text(opened,'Opened order: '+order.order_id+'. Select it explicitly before it can be added.');add.disabled=false;start.disabled=true}function renderSelected(){clean(selectedOrders);selected.forEach(order=>selectedOrders.append(orderCard(order)));selection.classList.remove('hidden');review.disabled=selected.length===0}function startFromOpened(){if(!openedOrderId)return;request('../orders/api/orders/'+encodeURIComponent(openedOrderId)).then(showVisibleOrder).catch(()=>setMessage('The handed-off order could not be opened.',true))}function addVisible(){if(!visibleOrder)return;if(!selected.some(order=>order.order_id===visibleOrder.order_id))selected.push(visibleOrder);renderSelected();setMessage('Visible opened order added. Choose Review draft to request the server preview.')}function field(label,value){const box=element('div');box.className='field';box.append(element('b',label),element('div',value));return box}function renderLines(data){const table=element('table'),head=element('thead'),row=element('tr');['Order','Line','Item','Qty','Source price','Current price status','Current price'].forEach(value=>row.append(element('th',value)));head.append(row);const body=element('tbody');data.lines.forEach(line=>{const tr=element('tr'),current=line.current_price||{};[line.order_id,line.line_ref,line.item_id,line.quantity,line.source_unit_price||'',current.status||'UNKNOWN',current.value||''].forEach(value=>tr.append(element('td',value)));body.append(tr)});table.append(head,body);return table}function decisionInputs(data){clean(conflicts);const unresolved=(data.unresolved||[]).filter(entry=>entry.conflict_id);unresolved.forEach(entry=>{const card=element('section');card.className='conflict';const id=entry.conflict_id;card.dataset.conflictId=id;card.append(element('h3','Conflict: '+id),element('p',entry.reason||'Unresolved conflict'));const choice=element('label'),radio=document.createElement('input');radio.type='radio';radio.name='decision-'+id;radio.value='manual';choice.append(radio,document.createTextNode(' Enter a manual value with a rationale'));const valueLabel=element('label','Manual value'),value=document.createElement('input');value.dataset.manualValue=id;const rationaleLabel=element('label','Rationale'),rationale=document.createElement('textarea');rationale.dataset.rationale=id;rationale.rows=2;card.append(choice,valueLabel,value,rationaleLabel,rationale);conflicts.append(card)});return unresolved.length}function renderProposal(data){proposal=data;previewRef=data.preview_ref;const proposalData=data.proposal;clean(reviewDetails);const grid=element('div');grid.className='grid';grid.append(field('Selected orders',proposalData.selected_order_ids.join(', ')),field('Document family',proposalData.document_family),field('Customer',proposalData.customer_id),field('Price status','Each line shown below'));reviewDetails.append(grid,element('h3','Exact selected lines'),renderLines(proposalData));const conflictCount=decisionInputs(proposalData);text($('#review-status'),conflictCount?'Resolve every listed conflict, then review again.':'Server preview is ready for confirmation.');reviewPanel.classList.remove('hidden');confirmation.checked=false;save.disabled=true;updateActor()}function decisions(){const output=[];for(const card of conflicts.children){const id=card.dataset.conflictId,choice=card.querySelector('input[type=radio]:checked'),value=card.querySelector('[data-manual-value]').value,rationale=card.querySelector('[data-rationale]').value;if(!choice||!value||!rationale){setMessage('Every conflict needs an explicit choice, manual value, and rationale.',true);return null}output.push({conflict_id:id,manual_value:value,rationale})}return output}function requestPreview(){const chosen=decisions();if(chosen===null)return;request('api/previews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({selected_order_ids:selected.map(order=>order.order_id),decisions:chosen})}).then(renderProposal).catch(()=>setMessage('The server did not accept this draft review.',true))}function updateSave(){save.disabled=!(confirmation.checked&&previewRef&&proposal&&proposal.proposal.ready_to_save===true&&activeActor())}confirmation.addEventListener('change',updateSave);window.addEventListener('apc-core-identity',updateSave);function saveDraft(){const actor=activeActor();if(!actor||!previewRef||!confirmation.checked)return;request('api/drafts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({preview_ref:previewRef,actor})}).then(result=>{text($('#review-status'),'Draft saved: '+result.draft_id);save.disabled=true;previewRef=''}).catch(()=>setMessage('Draft save was not accepted.',true))}start.onclick=startFromOpened;add.onclick=addVisible;review.onclick=requestPreview;save.onclick=saveDraft;const handoff=sessionStorage.getItem('apc-core-invoice-handoff')||'';sessionStorage.removeItem('apc-core-invoice-handoff');if(handoff){openedOrderId=handoff;text(opened,'Opened order handoff ready. Start the draft only after reviewing this order.');start.disabled=false}})();</script></body></html>"""
